//! Model Context Protocol types generated from the official JSON Schema.
//!
//! One module per protocol revision. Every module is generated by
//! `cargo xtask codegen` from the pinned `schema.json` and `schema.ts`; do not
//! edit them by hand.
//!
//! Items marked deprecated by the specification carry `#[deprecated]`, so
//! using them produces a compiler warning.
#![forbid(unsafe_code)]

#[allow(
    deprecated,
    missing_docs,
    unreachable_pub,
    rustdoc::bare_urls,
    rustdoc::broken_intra_doc_links,
    rustdoc::invalid_html_tags,
    clippy::doc_lazy_continuation,
    clippy::doc_overindented_list_items,
    clippy::large_enum_variant,
    clippy::too_many_arguments
)]
pub mod v2026_07_28;

/// The latest protocol revision supported by this crate.
pub use v2026_07_28 as latest;
